package ro.leo.visual;
import ro.leo.i18n.L;import org.json.*;import java.io.*;import java.util.*;
public final class ExpensesActivity extends PocketActivity {
 private String month=new java.text.SimpleDateFormat("yyyy-MM",Locale.ROOT).format(new Date());private File last;
 private JSONArray rows()throws Exception{JSONObject s=PocketStore.read(this,"expenses");return s.optJSONArray("entries")==null?new JSONArray():s.getJSONArray("entries");}
 protected void render()throws Exception{LinkedHashMap<String,Long> totals=ExpenseBook.totals(rows(),month,false);ArrayList<String> labels=new ArrayList<>();labels.add(L.t("Adaugă cheltuială"));labels.add(L.t("Istoric"));labels.add(L.t("Categorii"));labels.add(L.t("Luna")+" · "+month);labels.add(L.t("Exportă CSV"));for(Map.Entry<String,Long> e:totals.entrySet())labels.add(e.getKey()+" · "+ExpenseBook.money(e.getValue()));list(L.t("Cheltuieli Leo"),labels,0,new Choice(){public void pick(int at){if(at==0)add();else if(at==1)history();else if(at==2)categories();else if(at==3)edit(L.t("Luna"),new String[]{"YYYY-MM"},new String[]{month},new Saved(){public void save(String[] v)throws Exception{ExpenseBook.date(v[0]+"-01");month=v[0];home();}},goHome());else if(at==4)export();}},"",null);}
 private void add(){edit(L.t("Cheltuială nouă"),new String[]{L.t("Sumă"),L.t("Monedă"),L.t("Categorie"),L.t("Data · YYYY-MM-DD"),L.t("Notă")},new String[]{"","RON",L.t("Altele"),new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date()),""},new Saved(){public void save(String[] v)throws Exception{long amount=ExpenseBook.cents(v[0]);String currency=v[1].trim().toUpperCase(Locale.ROOT);if(!currency.matches("[A-Z]{3}")||v[2].trim().isEmpty())throw new IOException("Currency: 3 letters; category required");JSONArray all=rows();if(all.length()>=5000)throw new IOException("Maximum 5000 entries");all.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("cents",amount).put("currency",currency).put("category",UiText.preview(v[2],80)).put("date",ExpenseBook.date(v[3])).put("note",UiText.preview(v[4],500)));PocketStore.write(ExpensesActivity.this,"expenses",new JSONObject().put("entries",all));home();}},goHome());}
 private void history(){try{final JSONArray all=rows();final ArrayList<Integer> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(int n=all.length()-1;n>=0;n--){JSONObject e=all.getJSONObject(n);if(!e.getString("date").startsWith(month+"-"))continue;ids.add(n);labels.add(ExpenseBook.money(e.getLong("cents"))+" "+e.getString("currency")+" · "+e.getString("category")+"\n"+e.getString("date")+" · "+e.optString("note"));}list(L.t("Istoric cheltuieli"),labels,0,new Choice(){public void pick(final int at){remove(L.t("Ștergi cheltuiala?"),new Runnable(){public void run(){try{String selected=all.getJSONObject(ids.get(at)).getString("id");JSONArray latest=rows(),next=new JSONArray();for(int n=0;n<latest.length();n++)if(!selected.equals(latest.getJSONObject(n).getString("id")))next.put(latest.get(n));PocketStore.write(ExpensesActivity.this,"expenses",new JSONObject().put("entries",next));history();}catch(Exception e){problem(e);}}});}},"",null);back=goHome();}catch(Exception e){problem(e);}}
 private void categories(){try{ArrayList<String> labels=new ArrayList<>();for(Map.Entry<String,Long> e:ExpenseBook.totals(rows(),month,true).entrySet())labels.add(e.getKey()+"\n"+ExpenseBook.money(e.getValue()));list(L.t("Categorii")+" · "+month,labels,0,new Choice(){public void pick(int at){}},"",null);back=goHome();}catch(Exception e){problem(e);}}
 private void export(){job(L.t("Export cheltuieli"),new Work(){public void run()throws Exception{StringBuilder csv=new StringBuilder("date,amount,currency,category,note\n");JSONArray all=rows();for(int n=0;n<all.length();n++){JSONObject e=all.getJSONObject(n);csv.append(PocketStore.csv(e.getString("date"))).append(',').append(ExpenseBook.money(e.getLong("cents"))).append(',').append(PocketStore.csv(e.getString("currency"))).append(',').append(PocketStore.csv(e.getString("category"))).append(',').append(PocketStore.csv(e.optString("note"))).append('\n');}last=PocketStore.output(ExpensesActivity.this,"Expenses","expenses.csv");BackupEngine.write(last,csv.toString().getBytes("UTF-8"));}},new Runnable(){public void run(){exported(last);}});}
}
